SELECT b.NUM, IFNULL(a.FLOW_AVR, -99999) AS FLOW 
	FROM ( SELECT FLOW_AVR, DATE_FORMAT(FLOW_DATE, #{format}) AS NUM
			FROM FLOW_HIST
			WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
			AND FLOW_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM


		SELECT COUNT(*) AS cnt
		FROM FLOW_HIST
		WHERE AREA_CODE = #{area_code} AND DATA_TYPE = #{type} 
 		AND FLOW_DATE = #{where_date}

